def solve_math_problem(base: int, exponent_base: int, exponent_power: int, modulus: int) -> int:
    """
    Calculates (base^(exponent_base^exponent_power)) % modulus using Euler's Totient Theorem.
    """
    if modulus <= 0:
        raise ValueError("Modulus must be a positive integer.")
    if modulus == 1:
        return 0

    def get_phi(n: int) -> int:
        result = n
        p = 2
        while p * p <= n:
            if n % p == 0:
                while n % p == 0:
                    n //= p
                result -= result // p
            p += 1
        if n > 1:
            result -= result // n
        return result

    phi = get_phi(modulus)

    # Euler's Totient Theorem: a^phi(n) ≡ 1 (mod n) if gcd(a, n) == 1
    # We need to calculate exponent_base^exponent_power mod phi(modulus)
    # If gcd(base, modulus) != 1, we use the generalized version:
    # a^b ≡ a^(phi(m) + (b % phi(m))) (mod m) for b >= phi(m)

    exp = pow(exponent_base, exponent_power, phi)

    # Adjust exponent for the generalized Euler theorem
    if exponent_base**exponent_power >= phi:
        exp += phi

    return pow(base, exp, modulus)

