def solve_math_problem(a: int, b: int, n: int) -> int:
    """
    Solves the expression ((a + sqrt(b))^n + (a - sqrt(b))^n)^2 - ((a + sqrt(b))^n - (a - sqrt(b))^n)^2.
    Using the identity (x + y)^2 - (x - y)^2 = 4xy:
    Let x = (a + sqrt(b))^n and y = (a - sqrt(b))^n.
    The expression simplifies to 4 * (a + sqrt(b))^n * (a - sqrt(b))^n.
    Since (a + sqrt(b)) * (a - sqrt(b)) = a^2 - b,
    the expression simplifies to 4 * (a^2 - b)^n.
    """
    try:
        if not all(isinstance(i, int) for i in [a, b, n]):
            raise ValueError("All inputs must be integers.")

        result = 4 * pow(a**2 - b, n)
        return int(result)
    except Exception as e:
        raise RuntimeError(f"Calculation failed: {e}")

