from typing import Tuple

def solve_math_problem(sums: Tuple[int, ...]) -> float:
    """
    Calculates the sum of the original set of numbers given the sums of all 
    possible subsets of size (n-1).

    Formula: Sum of all numbers = (Sum of all given subset sums) / (n - 1)
    """
    n = len(sums)

    if n < 2:
        raise ValueError("At least two subset sums are required.")

    total_subset_sums = sum(sums)

    if total_subset_sums % (n - 1) != 0:
        return total_subset_sums / (n - 1)

    return total_subset_sums // (n - 1)

